<html lang="en">
  <head>
    <meta charset="UTF-8" />
    <meta name="viewport" content="width=device-width, initial-scale=1.0" />
    <title>Computer Languages Quiz</title>
    <style>
      :root {
        color-scheme: light;
        --bg: #f4f7fb;
        --card: rgba(255, 255, 255, 0.9);
        --text: #122033;
        --muted: #627089;
        --border: #d9e2ef;
        --accent: #3b82f6;
        --accent-strong: #2563eb;
        --shadow: 0 18px 50px rgba(15, 23, 42, 0.08);
      }

      * {
        box-sizing: border-box;
      }

      body {
        margin: 0;
        font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
        background:
          radial-gradient(circle at top, rgba(59, 130, 246, 0.14), transparent 34%),
          linear-gradient(180deg, #f8fbff 0%, var(--bg) 100%);
        color: var(--text);
        min-height: 100vh;
      }

      .app-shell {
        width: min(920px, calc(100% - 32px));
        margin: 40px auto;
      }

      .hero {
        margin-bottom: 20px;
      }

      .eyebrow {
        display: inline-block;
        font-size: 12px;
        letter-spacing: 0.12em;
        text-transform: uppercase;
        color: var(--accent-strong);
        font-weight: 700;
        margin-bottom: 10px;
      }

      h1 {
        margin: 0 0 8px;
        font-size: clamp(2rem, 4vw, 3rem);
        line-height: 1.05;
      }

      .subtitle {
        margin: 0;
        color: var(--muted);
        font-size: 1rem;
        max-width: 58ch;
      }

      .quiz-card {
        background: var(--card);
        border: 1px solid rgba(217, 226, 239, 0.8);
        border-radius: 24px;
        box-shadow: var(--shadow);
        overflow: hidden;
        backdrop-filter: blur(12px);
      }

      .quiz-form {
        padding: 28px;
      }

      .form-field {
        padding: 20px 0;
        border-bottom: 1px solid var(--border);
      }

      .form-field:first-child {
        padding-top: 0;
      }

      .form-field:last-of-type {
        border-bottom: 0;
        padding-bottom: 0;
      }

      .question-title {
        margin: 0 0 8px;
        font-size: 1.1rem;
      }

      .help-text {
        margin: 0 0 14px;
        color: var(--muted);
        font-size: 0.95rem;
      }

      .choices {
        display: grid;
        grid-template-columns: repeat(auto-fit, minmax(190px, 1fr));
        gap: 12px;
      }

      .choice {
        display: flex;
        align-items: flex-start;
        gap: 12px;
        padding: 14px 16px;
        border: 1px solid var(--border);
        border-radius: 16px;
        background: #fff;
        transition: transform 160ms ease, border-color 160ms ease, box-shadow 160ms ease;
        cursor: pointer;
      }

      .choice:hover {
        transform: translateY(-1px);
        border-color: rgba(59, 130, 246, 0.45);
        box-shadow: 0 10px 28px rgba(37, 99, 235, 0.08);
      }

      .choice input {
        margin-top: 2px;
        accent-color: var(--accent);
      }

      .choice span {
        line-height: 1.4;
      }

      .actions {
        display: flex;
        justify-content: flex-end;
        padding-top: 22px;
      }

      .submit-btn {
        appearance: none;
        border: 0;
        border-radius: 999px;
        background: linear-gradient(135deg, var(--accent), var(--accent-strong));
        color: #fff;
        font-weight: 700;
        font-size: 0.98rem;
        padding: 14px 22px;
        box-shadow: 0 14px 28px rgba(37, 99, 235, 0.24);
        cursor: pointer;
      }

      .submit-btn:hover {
        filter: brightness(1.03);
      }

      .result {
        margin-top: 18px;
        padding: 14px 16px;
        border-radius: 16px;
        background: #eff6ff;
        color: #1e3a8a;
      }

      @media (max-width: 640px) {
        .app-shell {
          width: min(100% - 20px, 920px);
          margin: 20px auto;
        }

        .quiz-form {
          padding: 20px;
        }
      }
    </style>
  </head>
  <body>
    <div id="root"></div>

    <script src="https://unpkg.com/react@18/umd/react.development.js" crossorigin></script>
    <script src="https://unpkg.com/react-dom@18/umd/react-dom.development.js" crossorigin></script>
    <script src="https://unpkg.com/@babel/standalone/babel.min.js"></script>
    <script type="text/babel">
      const quizQuestions = [
        {
          id: "q1",
          prompt: "Which of these are programming languages?",
          helpText: "Select every option that is actually a language used to write software.",
          choices: ["Python", "HTML", "JavaScript", "CSS"],
        },
        {
          id: "q2",
          prompt: "Which of these are compiled languages?",
          choices: ["C", "Java", "Ruby", "Go"],
        },
        {
          id: "q3",
          prompt: "Which of these are commonly used for web development?",
          choices: ["TypeScript", "PHP", "SQL", "Scratch"],
        },
      ];

      function Question({ question, selectedValues, onToggle }) {
        return (
          <div className="form-field">
            <h2 className="question-title">{question.prompt}</h2>
            {question.helpText ? <p className="help-text">{question.helpText}</p> : null}
            <div className="choices" role="group" aria-label={question.prompt}>
              {question.choices.map((choice) => {
                const checkboxId = `${question.id}-${choice.toLowerCase().replace(/\s+/g, "-")}`;
                return (
                  <label className="choice" key={choice} htmlFor={checkboxId}>
                    <input
                      id={checkboxId}
                      type="checkbox"
                      checked={selectedValues.includes(choice)}
                      onChange={() => onToggle(question.id, choice)}
                    />
                    <span>{choice}</span>
                  </label>
                );
              })}
            </div>
          </div>
        );
      }

      function QuizApp() {
        const [answers, setAnswers] = React.useState({});
        const [result, setResult] = React.useState("");

        const handleToggle = (questionId, choice) => {
          setAnswers((current) => {
            const selected = current[questionId] || [];
            const next = selected.includes(choice)
              ? selected.filter((item) => item !== choice)
              : [...selected, choice];

            return { ...current, [questionId]: next };
          });
        };

        const handleSubmit = (event) => {
          event.preventDefault();
          const summary = quizQuestions
            .map((question) => {
              const selected = answers[question.id] || [];
              return `${question.prompt} ${selected.length ? selected.join(", ") : "No answers selected"}`;
            })
            .join(" | ");
          setResult(summary);
        };

        return (
          <main className="app-shell">
            <header className="hero">
              <div className="eyebrow">Quiz</div>
              <h1>Computer Languages</h1>
              <p className="subtitle">
                A quick multi-select quiz that looks and behaves like a modern product form.
              </p>
            </header>

            <section className="quiz-card">
              <form className="quiz-form" onSubmit={handleSubmit}>
                {quizQuestions.map((question) => (
                  <Question
                    key={question.id}
                    question={question}
                    selectedValues={answers[question.id] || []}
                    onToggle={handleToggle}
                  />
                ))}

                <div className="actions">
                  <button className="submit-btn" type="submit">
                    Submit
                  </button>
                </div>

                {result ? <div className="result">{result}</div> : null}
              </form>
            </section>
          </main>
        );
      }

      ReactDOM.createRoot(document.getElementById("root")).render(<QuizApp />);
    </script>
  </body>
</html>
